;; =============================================================================
;; DUAL STACKING V3 - CORE
;; Enrollment, blacklist, off-chain reward distribution, Merkle verification.
;; =============================================================================

;; ===================================
;; ERROR CONSTANTS
;; ===================================

(define-constant ERR_ALREADY_ENROLLED (err u101))
(define-constant ERR_NOT_ENROLLED (err u102))
(define-constant ERR_USER_BLACKLISTED (err u103))
(define-constant ERR_ENROLL_MINIMUM_HOLD_NOT_MET (err u104))
(define-constant ERR_NOT_BLACKLISTED (err u105))
(define-constant ERR_NOT_ADMIN (err u201))
(define-constant ERR_SNAPSHOT_ROOT_NOT_FOUND (err u301))
(define-constant ERR_REWARDS_ROOT_NOT_FOUND (err u302))
(define-constant ERR_CONSENSUS_ENCODING_FAILED (err u303))
(define-constant ERR_PROOF_ELEMENT_MISSING (err u304))
(define-constant ERR_FOLD_FAILED (err u305))

;; Indices 0..31 for folding over Merkle proof steps
(define-constant PROOF_INDICES (list u0 u1 u2 u3 u4 u5 u6 u7 u8 u9 u10 u11 u12 u13 u14 u15 u16 u17 u18 u19 u20 u21 u22 u23 u24 u25 u26 u27 u28 u29 u30 u31))

;; ===================================
;; STATE
;; ===================================

(define-data-var admin principal tx-sender)
(define-data-var min-sbtc-hold-required-for-enrollment uint u10000)

;; ===================================
;; MAPS - PARTICIPANTS & BLACKLIST
;; ===================================

(define-map participants
  { address: principal }
  {
    stacking-address: principal,
    rewarded-address: principal,
    tracking-address: principal,
  }
)

(define-map blacklist
  { address: principal }
  { blacklisted: bool }
)

;; Merkle roots committed per cycle (off-chain transparency)
;; snapshots-merkle-root: one root per (cycle-id, snapshot-index)
;; rewards-merkle-root: one root per cycle-id for reward distribution
(define-map snapshots-merkle-root
  { cycle-id: uint, snapshot-index: uint }
  (buff 32)
)

(define-map rewards-merkle-root
  { cycle-id: uint }
  (buff 32)
)

;; ===================================
;; ENROLLMENT
;; ===================================

(define-read-only (meets-enrollment-minimum (address principal))
  (>= (unwrap-panic (contract-call? 'SM3VDXK3WZZSA84XXFKAFAF15NNZX32CTSG82JFQ4.sbtc-token get-balance-available address))
    (var-get min-sbtc-hold-required-for-enrollment)
  )
)

(define-public (enroll (rewarded-address (optional principal)))
  (let (
      (rewards-recipient (default-to contract-caller rewarded-address))
    )
    (asserts!
      (is-none (map-get? participants { address: contract-caller }))
      ERR_ALREADY_ENROLLED
    )
    (asserts!
      (meets-enrollment-minimum contract-caller)
      ERR_ENROLL_MINIMUM_HOLD_NOT_MET
    )
    (asserts!
      (is-none (map-get? blacklist { address: contract-caller }))
      ERR_USER_BLACKLISTED
    )
    (print {
      bitcoin-block-height: burn-block-height,
      reward-address: rewards-recipient,
      enrolled-address: contract-caller,
      stacking-address: contract-caller,
      tracking-address: contract-caller,
      function-name: "enroll",
    })
    (ok (map-set participants { address: contract-caller } {
      rewarded-address: rewards-recipient,
      stacking-address: contract-caller,
      tracking-address: contract-caller,
    }))
  )
)

(define-public (enroll-defi-batch (defi-contracts (list
  900
  {
    defi-contract: principal,
    tracking-address: principal,
    rewarded-address: principal,
    stacking-address: (optional principal),
  }
)))
  (begin
    (asserts! (is-eq contract-caller (var-get admin)) ERR_NOT_ADMIN)
    (ok (map enroll-defi defi-contracts))
  )
)

(define-private (enroll-defi (entry {
  defi-contract: principal,
  tracking-address: principal,
  rewarded-address: principal,
  stacking-address: (optional principal),
}))
  (let (
      (defi-contract (get defi-contract entry))
      (tracking-address (get tracking-address entry))
      (rewarded-address (get rewarded-address entry))
      (stacking-address (get stacking-address entry))
      (stacking-recipient (default-to defi-contract stacking-address))
    )
    (asserts!
      (is-none (map-get? participants { address: defi-contract }))
      ERR_ALREADY_ENROLLED
    )
    (asserts! (is-none (map-get? blacklist { address: defi-contract }))
      ERR_USER_BLACKLISTED
    )
    (print {
      bitcoin-block-height: burn-block-height,
      reward-address: rewarded-address,
      stacking-address: stacking-recipient,
      tracking-address: tracking-address,
      enrolled-address: defi-contract,
      function-name: "enroll",
    })
    (ok (map-set participants { address: defi-contract } {
      rewarded-address: rewarded-address,
      stacking-address: stacking-recipient,
      tracking-address: tracking-address,
    }))
  )
)

;; ===================================
;; OPT OUT
;; ===================================

(define-public (opt-out)
  (begin
    (asserts!
      (is-some (map-get? participants { address: contract-caller }))
      ERR_NOT_ENROLLED
    )
    (ok (remove-participant contract-caller))
  )
)

(define-public (opt-out-defi-batch (defi-contracts (list 200 principal)))
  (begin
    (asserts! (is-eq contract-caller (var-get admin)) ERR_NOT_ADMIN)
    (ok (map opt-out-defi defi-contracts))
  )
)

(define-private (opt-out-defi (defi-contract principal))
  (begin
    (asserts!
      (is-some (map-get? participants { address: defi-contract }))
      ERR_NOT_ENROLLED
    )
    (ok (remove-participant defi-contract))
  )
)

(define-private (remove-participant (address principal))
  (begin
    (print {
      bitcoin-block-height: burn-block-height,
      enrolled-address: address,
      function-name: "opt-out",
    })
    (map-delete participants { address: address })
  )
)

;; ===================================
;; BLACKLIST
;; ===================================

(define-public (add-blacklisted-batch (addresses (list 200 principal)))
  (begin
    (asserts! (is-eq (var-get admin) contract-caller) ERR_NOT_ADMIN)
    (ok (map add-blacklisted addresses))
  )
)

(define-private (add-blacklisted (address principal))
  (let ((participant (map-get? participants { address: address })))
    (if (is-some participant)
      (begin
        (remove-participant address)
        (print {
          bitcoin-block-height: burn-block-height,
          reward-address: (get rewarded-address participant),
          stacking-address: (get stacking-address participant),
          tracking-address: (get tracking-address participant),
          enrolled-address: address,
          function-name: "blacklisted",
        })
        (ok (map-set blacklist { address: address } { blacklisted: true }))
      )
      (begin
        (print {
          bitcoin-block-height: burn-block-height,
          enrolled-address: address,
          function-name: "blacklisted",
        })
        (ok (map-set blacklist { address: address } { blacklisted: true }))
      )
    )
  )
)

(define-public (remove-blacklisted-batch (addresses (list 200 principal)))
  (begin
    (asserts! (is-eq (var-get admin) contract-caller) ERR_NOT_ADMIN)
    (ok (map remove-blacklisted addresses))
  )
)

(define-private (remove-blacklisted (address principal))
  (begin
    (asserts! (is-some (map-get? blacklist { address: address }))
      ERR_NOT_BLACKLISTED
    )
    (print {
      bitcoin-block-height: burn-block-height,
      enrolled-address: address,
      function-name: "unblacklisted",
    })
    (ok (map-delete blacklist { address: address }))
  )
)

;; ===================================
;; CONFIGURATION - MINIMUM ENROLLMENT
;; ===================================

(define-public (update-min-sbtc-hold-required-for-enrollment (new-min-hold uint))
  (begin
    (asserts! (is-eq contract-caller (var-get admin)) ERR_NOT_ADMIN)
    (print {
      bitcoin-block-height: burn-block-height,
      min-sbtc-hold-required-for-enrollment: new-min-hold,
      function-name: "update-min-enrollment",
    })
    (ok (var-set min-sbtc-hold-required-for-enrollment new-min-hold))
  )
)

;; ===================================
;; REWARD & TRACKING ADDRESSES
;; ===================================

(define-public (change-reward-address (new-address principal))
  (let ((participant (unwrap! (map-get? participants { address: contract-caller })
      ERR_NOT_ENROLLED
    )))
    (print {
      bitcoin-block-height: burn-block-height,
      reward-address: new-address,
      stacking-address: (get stacking-address participant),
      tracking-address: (get tracking-address participant),
      enrolled-address: contract-caller,
      function-name: "update-participant-details",
    })
    (ok (map-set participants { address: contract-caller }
      (merge participant { rewarded-address: new-address })
    ))
  )
)

(define-public (change-addresses-defi-batch (defi-contracts (list
  900
  {
    defi-contract: principal,
    tracking-address: (optional principal),
    rewarded-address: (optional principal),
    stacking-address: (optional principal),
  }
)))
  (begin
    (asserts! (is-eq contract-caller (var-get admin)) ERR_NOT_ADMIN)
    (ok (map change-addresses-defi-one defi-contracts))
  )
)

(define-private (change-addresses-defi-one (entry {
  defi-contract: principal,
  tracking-address: (optional principal),
  rewarded-address: (optional principal),
  stacking-address: (optional principal),
}))
  (let (
      (defi-contract (get defi-contract entry))
      (participant (unwrap! (map-get? participants { address: defi-contract })
        ERR_NOT_ENROLLED
      ))
    )
    (let (
        (local-reward-address (default-to (get rewarded-address participant)
          (get rewarded-address entry)
        ))
        (local-stacking-address (default-to (get stacking-address participant)
          (get stacking-address entry)
        ))
        (local-tracking-address (default-to (get tracking-address participant)
          (get tracking-address entry)
        ))
      )
      (print {
        bitcoin-block-height: burn-block-height,
        reward-address: local-reward-address,
        stacking-address: local-stacking-address,
        tracking-address: local-tracking-address,
        enrolled-address: defi-contract,
        function-name: "update-participant-details",
      })
      (map-set participants { address: defi-contract } {
        rewarded-address: local-reward-address,
        tracking-address: local-tracking-address,
        stacking-address: local-stacking-address,
      })
      (ok true)
    )
  )
)

;; ===================================
;; OFF-CHAIN REWARD DISTRIBUTION (ADMIN)
;; ===================================

(define-public (distribute-rewards (data-rewarded (list 900 {
  amount: uint,
  recipient: principal,
})))
  (begin
    (asserts! (is-eq contract-caller (var-get admin)) ERR_NOT_ADMIN)
    (ok (map distribute-reward-user data-rewarded))
  )
)

(define-private (distribute-reward-user (data {
  amount: uint,
  recipient: principal,
}))
  (let (
      (amount (get amount data))
      (recipient (get recipient data))
    )
    (restrict-assets? (var-get admin)
      ((with-ft 'SM3VDXK3WZZSA84XXFKAFAF15NNZX32CTSG82JFQ4.sbtc-token
        "sbtc-token" amount
      ))
      (try! (contract-call?
        'SM3VDXK3WZZSA84XXFKAFAF15NNZX32CTSG82JFQ4.sbtc-token transfer
        amount (var-get admin) recipient none
      ))
    )
  )
)

;; ===================================
;; MERKLE VERIFIER - HASHING
;; ===================================
;; Verifies (principal, amount) leaves against roots committed by admin.
;; Off-chain builders must use the same consensus encoding and tagged hashes.
;; Domain separation:
;;   LEAF   = sha256( "merkle-leaf"   ++ principal ++ field-id ++ amount )
;;   PARENT = sha256( "merkle-parent" ++ left ++ right )

(define-constant MERKLE_LEAF_TAG 0x6d65726b6c652d6c656166) ;; "merkle-leaf"
(define-constant MERKLE_PARENT_TAG 0x6d65726b6c652d706172656e74) ;; "merkle-parent"

(define-private (hash-leaf (principal principal) (field-id uint) (amount uint))
  (let (
      (principal-buf (try! (match (to-consensus-buff? principal) p (ok p) ERR_CONSENSUS_ENCODING_FAILED)))
      (field-buf (try! (match (to-consensus-buff? field-id) p (ok p) ERR_CONSENSUS_ENCODING_FAILED)))
      (amount-buf (try! (match (to-consensus-buff? amount) p (ok p) ERR_CONSENSUS_ENCODING_FAILED)))
    )
    (ok (sha256 (concat MERKLE_LEAF_TAG (concat principal-buf (concat field-buf amount-buf)))))
  )
)

(define-private (hash-parent (left (buff 32)) (right (buff 32)))
  (sha256 (concat MERKLE_PARENT_TAG (concat left right)))
)

;; ===================================
;; MERKLE VERIFIER - PROOF FOLD
;; ===================================
;; Parent = hash(left || right). Position true = sibling is left.

(define-private (fold-proof-step-inner
    (idx uint)
    (acc (response { current: (optional (buff 32)), proof: (list 32 (buff 32)), positions: (list 32 bool) } uint))
  )
  (let (
      (data (unwrap! acc ERR_FOLD_FAILED))
      (current (get current data))
      (proof (get proof data))
      (positions (get positions data))
    )
    (if (is-none current)
      (ok data)
      (if (>= idx (len proof))
        (ok data)
        (let (
            (current-buf (unwrap! current ERR_FOLD_FAILED))
            (proof-hash (unwrap! (element-at proof idx) ERR_PROOF_ELEMENT_MISSING))
            (sibling-left (unwrap! (element-at positions idx) ERR_PROOF_ELEMENT_MISSING))
            (parent (if sibling-left
              (hash-parent proof-hash current-buf)
              (hash-parent current-buf proof-hash)
            ))
          )
          (ok {
            current: (some parent),
            proof: proof,
            positions: positions
          })
        )
      )
    )
  )
)

(define-private (verify-proof (leaf (buff 32)) (proof (list 32 (buff 32))) (positions (list 32 bool)) (expected-root (buff 32)))
  (let (
      (initial { current: (some leaf), proof: proof, positions: positions })
      (folded (try! (fold fold-proof-step-inner PROOF_INDICES (ok initial))))
      (computed-root (get current folded))
      (final-root (if (is-some computed-root) (try! (match computed-root r (ok r) ERR_FOLD_FAILED)) leaf))
    )
    (ok (is-eq final-root expected-root))
  )
)

;; ===================================
;; MERKLE VERIFIER - READ-ONLY
;; ===================================

(define-read-only (verify-snapshot
    (cycle uint)
    (snapshot-idx uint)
    (field-id uint)
    (amount uint)
    (proof (list 32 (buff 32)))
    (positions (list 32 bool))
  )
  (let (
      (root (try! (match (map-get? snapshots-merkle-root { cycle-id: cycle, snapshot-index: snapshot-idx }) r (ok r) ERR_SNAPSHOT_ROOT_NOT_FOUND)))
      (leaf (try! (hash-leaf tx-sender field-id amount)))
      (valid (try! (verify-proof leaf proof positions root)))
    )
    (ok valid)
  )
)

(define-read-only (verify-reward
    (cycle uint)
    (field-id uint)
    (amount uint)
    (proof (list 32 (buff 32)))
    (positions (list 32 bool))
  )
  (let (
      (root (try! (match (map-get? rewards-merkle-root { cycle-id: cycle }) r (ok r) ERR_REWARDS_ROOT_NOT_FOUND)))
      (leaf (try! (hash-leaf tx-sender field-id amount)))
      (valid (try! (verify-proof leaf proof positions root)))
    )
    (ok valid)
  )
)

;; ===================================
;; MERKLE VERIFIER - ADMIN (SET ROOTS)
;; ===================================

(define-public (set-snapshot-root (cycle uint) (snapshot-idx uint) (root (buff 32)))
  (begin
    (asserts! (is-eq contract-caller (var-get admin)) ERR_NOT_ADMIN)
    (map-set snapshots-merkle-root { cycle-id: cycle, snapshot-index: snapshot-idx } root)
    (ok true)
  )
)

(define-public (set-rewards-root (cycle uint) (root (buff 32)))
  (begin
    (asserts! (is-eq contract-caller (var-get admin)) ERR_NOT_ADMIN)
    (map-set rewards-merkle-root { cycle-id: cycle } root)
    (ok true)
  )
)

(define-public (change-admin (address principal))
  (begin
    (asserts! (is-eq contract-caller (var-get admin)) ERR_NOT_ADMIN)
    (ok (var-set admin address))
  )
)

;; ===================================
;; MERKLE VERIFIER - READ-ONLY GETTERS
;; ===================================

(define-read-only (get-rewards-root (cycle uint))
  (map-get? rewards-merkle-root { cycle-id: cycle })
)

(define-read-only (get-snapshot-root (cycle uint) (snapshot-idx uint))
  (map-get? snapshots-merkle-root { cycle-id: cycle, snapshot-index: snapshot-idx })
)
